fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Assumes 0 <= end < v.len()
    let mut max_val = v[0];
    let mut max_idx = 0;
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Assumes 0 <= start < v.len()
    let mut min_val = v[start];
    let mut min_idx = start;
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // If p is the last index, there's no suffix to compare, so it's vacuously true.
    if p + 1 >= v.len() {
        return true;
    }
    let (max_pref, _) = find_max_in_prefix(v, p);
    let (min_suf, _) = find_min_in_suffix(v, p + 1);
    max_pref < min_suf
}

